<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';msp2RequireAccess();$flash=msp2PullFlash();$error=null;$bancos=[];$cajas=[];$movimientos=[];$conciliaciones=[];$cierres=[];$usuarios=[];
$desde=trim((string)($_GET['desde']??date('Y-m-01')));$hasta=trim((string)($_GET['hasta']??date('Y-m-d')));$cuenta=filter_input(INPUT_GET,'cuenta',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$fechaCaja=trim((string)($_GET['fecha_caja']??date('Y-m-d')));
function tcMonto(mixed $v):string{return '$ '.number_format((float)$v,2,',','.');}
try{
 $bancos=$conn->query("SELECT * FROM dbo.msp_vw_tesoreria_saldos WHERE tipo_cuenta=N'BANCO' AND activo=1 ORDER BY banco,nombre_cuenta")->fetchAll()?:[];$cajas=$conn->query("SELECT * FROM dbo.msp_vw_tesoreria_saldos WHERE tipo_cuenta=N'CAJA' AND activo=1 ORDER BY nombre_cuenta")->fetchAll()?:[];
 if($cuenta){$stmt=$conn->prepare("SELECT * FROM dbo.msp_tesoreria_movimientos WHERE id_cuenta_tesoreria=:cuenta AND fecha_movimiento BETWEEN :desde AND :hasta AND estado_movimiento=N'VIGENTE' ORDER BY fecha_movimiento,id_movimiento_tesoreria");$stmt->execute([':cuenta'=>(int)$cuenta,':desde'=>$desde,':hasta'=>$hasta]);$movimientos=$stmt->fetchAll()?:[];}
 $usuarios=$conn->query("SELECT id,nombre_completo,UserName FROM dbo.cr_usuarios WHERE estado_id=1 ORDER BY nombre_completo,UserName")->fetchAll()?:[];
 $conciliaciones=$conn->query("SELECT TOP(50)c.*,t.nombre_cuenta,t.banco,(SELECT COUNT(*) FROM dbo.msp_tesoreria_conciliacion_items i WHERE i.id_conciliacion_tesoreria=c.id_conciliacion_tesoreria) items FROM dbo.msp_tesoreria_conciliaciones c JOIN dbo.msp_tesoreria_cuentas t ON t.id_cuenta_tesoreria=c.id_cuenta_tesoreria ORDER BY c.fecha_registro DESC")->fetchAll()?:[];
 $cierres=$conn->query("SELECT TOP(50)c.*,t.nombre_cuenta FROM dbo.msp_tesoreria_cierres_caja c JOIN dbo.msp_tesoreria_cuentas t ON t.id_cuenta_tesoreria=c.id_cuenta_tesoreria ORDER BY c.fecha_cierre DESC,c.id_cierre_caja DESC")->fetchAll()?:[];
}catch(Throwable $e){$error='No fue posible cargar conciliación y cierres.';}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Conciliación y cierre | MSP</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css"><link rel="stylesheet" href="/portalgp/styles.css"></head><body class="gp-layout bg-light"><?php include dirname(__DIR__,2).'/templates/header.php';msp2RenderCsrfAutoFieldScript();?><main class="gp-main container-fluid py-4 px-lg-4"><div class="d-flex flex-wrap justify-content-between gap-2 mb-3"><div><p class="text-muted mb-1">MSP / Tesorería</p><h1 class="h3">Conciliación bancaria y cierre de caja</h1></div><div class="d-flex gap-2"><a class="btn btn-outline-dark btn-sm align-self-start" href="<?php echo msp2Escape(msp2Url('garantias/index.php'));?>"><i class="bi bi-arrow-left me-1"></i>Volver a Garantías</a><a class="btn btn-outline-secondary btn-sm align-self-start" href="<?php echo msp2Escape(msp2Url('tesoreria/control_diario.php'));?>">Tesorería diaria</a></div></div><?php if(is_array($flash)):?><div class="alert alert-<?php echo msp2Escape((string)($flash['type']??'info'));?>"><?php echo msp2Escape((string)($flash['message']??''));?></div><?php endif;if($error):?><div class="alert alert-danger"><?php echo msp2Escape($error);?></div><?php endif;?>
<div class="row g-4"><div class="col-xl-7"><div class="card shadow-sm"><div class="card-header fw-semibold">Conciliación bancaria</div><div class="card-body"><form method="get" class="row g-2 align-items-end mb-3"><div class="col-md-5"><label class="form-label">Cuenta</label><select name="cuenta" class="form-select" required><option value="">Seleccionar</option><?php foreach($bancos as $b):?><option value="<?php echo (int)$b['id_cuenta_tesoreria'];?>" <?php echo (int)$cuenta===(int)$b['id_cuenta_tesoreria']?'selected':'';?>><?php echo msp2Escape(($b['banco']??'').' · '.$b['nombre_cuenta'].' · '.tcMonto($b['saldo_actual']));?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Desde</label><input type="date" name="desde" class="form-control" value="<?php echo msp2Escape($desde);?>"></div><div class="col-md-3"><label class="form-label">Hasta</label><input type="date" name="hasta" class="form-control" value="<?php echo msp2Escape($hasta);?>"></div><div class="col-md-1"><button class="btn btn-primary">Ver</button></div></form>
<?php if($cuenta):?><form method="post" action="<?php echo msp2Escape(msp2Url('tesoreria/guardar_conciliacion.php'));?>"><?php msp2CsrfField();?><input type="hidden" name="id_cuenta_tesoreria" value="<?php echo (int)$cuenta;?>"><input type="hidden" name="fecha_desde" value="<?php echo msp2Escape($desde);?>"><input type="hidden" name="fecha_hasta" value="<?php echo msp2Escape($hasta);?>"><div class="table-responsive mb-3" style="max-height:330px"><table class="table table-sm align-middle"><thead class="table-light sticky-top"><tr><th><input type="checkbox" id="checkAll"></th><th>Fecha</th><th>Operación</th><th>Referencia</th><th class="text-end">Monto</th><th>Estado</th></tr></thead><tbody><?php if($movimientos===[]):?><tr><td colspan="6" class="text-center text-muted">Sin movimientos.</td></tr><?php endif;foreach($movimientos as $m):?><tr><td><input class="form-check-input mov-check" type="checkbox" name="movimientos[]" value="<?php echo (int)$m['id_movimiento_tesoreria'];?>" <?php echo (int)$m['conciliado']===1?'disabled':'';?>></td><td><?php echo msp2Escape(substr((string)$m['fecha_movimiento'],0,10));?></td><td><?php echo msp2Escape(str_replace('_',' ',(string)$m['tipo_movimiento']));?></td><td><?php echo msp2Escape((string)($m['referencia']??'-'));?></td><td class="text-end <?php echo $m['naturaleza']==='E'?'text-success':'text-danger';?>"><?php echo $m['naturaleza']==='S'?'-':'';?><?php echo msp2Escape(tcMonto($m['monto']));?></td><td><?php echo (int)$m['conciliado']===1?'Conciliado':'Pendiente';?></td></tr><?php endforeach;?></tbody></table></div><div class="row g-2"><div class="col-md-5"><label class="form-label">Saldo final según cartola</label><input type="number" step="0.01" name="saldo_cartola" class="form-control" required></div><div class="col-md-7"><label class="form-label">Observaciones</label><input name="observaciones" maxlength="500" class="form-control"></div><div class="col-12 text-end"><button class="btn btn-success">Guardar conciliación</button></div></div></form><?php elseif($bancos===[]):?><div class="alert alert-warning mb-0">Configura una cuenta bancaria antes de conciliar.</div><?php endif;?></div></div></div>
<div class="col-xl-5"><div class="card shadow-sm"><div class="card-header fw-semibold">Cerrar caja diaria</div><div class="card-body"><form method="post" action="<?php echo msp2Escape(msp2Url('tesoreria/cerrar_caja.php'));?>" class="row g-3"><?php msp2CsrfField();?><div class="col-12"><label class="form-label">Caja</label><select name="id_cuenta_tesoreria" class="form-select" required><?php foreach($cajas as $c):?><option value="<?php echo (int)$c['id_cuenta_tesoreria'];?>"><?php echo msp2Escape($c['nombre_cuenta'].' · Saldo actual '.tcMonto($c['saldo_actual']));?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Fecha</label><input type="date" name="fecha_cierre" class="form-control" value="<?php echo msp2Escape($fechaCaja);?>" required></div><div class="col-md-6"><label class="form-label">Efectivo contado</label><input type="number" min="0" step="0.01" name="efectivo_contado" class="form-control" required></div><div class="col-12"><label class="form-label">Observaciones</label><textarea name="observaciones" maxlength="500" rows="2" class="form-control"></textarea></div><div class="col-12 d-grid"><button class="btn btn-primary" onclick="return confirm('¿Cerrar esta caja para la fecha indicada?');">Registrar cierre</button></div></form></div></div></div></div>
<div class="row g-4 mt-1"><div class="col-xl-7"><div class="card shadow-sm"><div class="card-header fw-semibold">Historial de conciliaciones</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Cuenta</th><th>Período</th><th class="text-end">Sistema</th><th class="text-end">Cartola</th><th class="text-end">Diferencia</th><th>Estado</th></tr></thead><tbody><?php if($conciliaciones===[]):?><tr><td colspan="6" class="text-center text-muted">Sin conciliaciones.</td></tr><?php endif;foreach($conciliaciones as $c):?><tr><td><?php echo msp2Escape(($c['banco']??'').' · '.$c['nombre_cuenta']);?></td><td><?php echo msp2Escape(substr((string)$c['fecha_desde'],0,10).' a '.substr((string)$c['fecha_hasta'],0,10));?></td><td class="text-end"><?php echo msp2Escape(tcMonto($c['saldo_sistema']));?></td><td class="text-end"><?php echo msp2Escape(tcMonto($c['saldo_cartola']));?></td><td class="text-end"><?php echo msp2Escape(tcMonto($c['diferencia']));?></td><td><span class="badge text-bg-<?php echo $c['estado_conciliacion']==='CUADRADA'?'success':'warning';?>"><?php echo msp2Escape((string)$c['estado_conciliacion']);?></span></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-xl-5"><div class="card shadow-sm"><div class="card-header fw-semibold">Historial de cierres</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Fecha</th><th>Caja</th><th class="text-end">Sistema</th><th class="text-end">Contado</th><th class="text-end">Dif.</th><th>Estado</th></tr></thead><tbody><?php if($cierres===[]):?><tr><td colspan="6" class="text-center text-muted">Sin cierres.</td></tr><?php endif;foreach($cierres as $c):?><tr><td><?php echo msp2Escape(substr((string)$c['fecha_cierre'],0,10));?></td><td><?php echo msp2Escape((string)$c['nombre_cuenta']);?></td><td class="text-end"><?php echo msp2Escape(tcMonto($c['saldo_sistema']));?></td><td class="text-end"><?php echo msp2Escape(tcMonto($c['efectivo_contado']));?></td><td class="text-end"><?php echo msp2Escape(tcMonto($c['diferencia']));?></td><td><span class="badge text-bg-<?php echo $c['estado_cierre']==='CUADRADO'?'success':'warning';?>"><?php echo msp2Escape((string)$c['estado_cierre']);?></span></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
</main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script><script>document.getElementById('checkAll')?.addEventListener('change',e=>document.querySelectorAll('.mov-check:not(:disabled)').forEach(x=>x.checked=e.target.checked));</script></body></html>
